     AND q.expire_date IS NOT NULL AND q.expire_date BETWEEN DATE_ADD(CURDATE(), INTERVAL 31 DAY) AND DATE_ADD(CURDATE(), INTERVAL 60 DAY)
     AND q.expire_date IS NULL
