UPDATE bid_qualification
qual_type = #{qualType}, name = #{name}, cert_no = #{certNo}, qual_level = #{qualLevel}, owner_type = #{ownerType}, owner_user_id = #{ownerUserId}, owner_name = #{ownerName}, issue_date = #{issueDate}, expire_date = #{expireDate}, warn_days = #{warnDays}, file_url = #{fileUrl}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
